skus = list_skus('kestrel-harbor')
total = 0
skipped = 0
for sku in skus:
    try:
        stock = get_stock(sku)
        total += stock['on_hand']
    except ToolError:
        skipped += 1
print(f'{total},{skipped}')

ids = ['C-6057','C-5623','C-7623','C-7804','C-9696','C-7014','C-9919','C-4806','C-1137','C-9082','C-7561','C-7109','C-1008','C-1303','C-2150']
orders = {cid: len(list_orders(cid)) for cid in ids}
mx = max(orders.values())
for cid in ids:
    if orders[cid] == mx:
        print(cid, mx)

tickets = list_tickets('open')
selected = []
for tid in tickets:
    t = get_ticket(tid)
    if t['age_days'] > 21:
        selected.append(tid)
for tid in selected:
    update_ticket(tid, 'closed')
print(len(selected))

tickets = list_tickets('open')
res = []
for t in tickets:
    info = get_ticket(t)
    if info['priority'] == 'high':
        cust = get_customer(info['customer_id'])
        if cust['tier'] == 'gold':
            res.append((info['customer_id'], cust['name']))
# distinct customers
seen = set()
uniq = []
for cid, name in res:
    if cid not in seen:
        seen.add(cid)
        uniq.append((cid, name))
for cid, name in uniq:
    send_message(cid, 'We are on it.')
print(len(uniq))
